        if self.gsl is None:
            self.load_library()
        if not isinstance(np_array, np.ndarray):
            raise ValueError("Input must be a NumPy array")
        gsl_matrix = ctypes.POINTER(ctypes.c_double * len(np_array))()
        for i in range(len(np_array)):
            for j in range(len(np_array[i])):
                gsl_matrix[i][j] = np_array[i, j].real
        return gsl_matrix

    def gsl_vector_to_numpy(self, gsl_vector, size):
        if self.gsl is None:
            self.load_library()
        numpy_array = np.zeros((size, 1), dtype=np.complex)
        for i in range(size):
            numpy_array[i] = complex(gsl_vector.contents.data[i])
        return numpy_array

