        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except OSError as e:
        raise GSLException("Failed to load GSL libraries.") from e
    return gslcblas, gsl

def configure_gsl_stats_mean(gsl):
    try:
        gsl_stats_mean = gsl.lib.gsl_stats_mean
        gsl_stats_mean.argtypes = [ctypes.POINTER(ctypes.c_double)]
        gsl_stats_mean.restype = ctypes.c_double
    except AttributeError as e:
        raise GSLException("Failed to configure 'gsl_stats_mean'.") from e
    return gsl_stats_mean

def compute_mean(data, stride, size):
    gslcblas, gsl = load_gsl_libraries()
    gsl_stats_mean = configure_gsl_stats_mean(gsl)
    try:
        mean = gsl_stats_mean(ctypes.pointer(data), stride, size)
    except GSLException as e:
        raise GSLException("Failed to compute mean.") from e
    return mean

