class GSLMatrix:
    def __init__(self, data):
        self.data = data

    @staticmethod
    def create_gsl_matrix(data):
        # Create a GSL matrix from a 2D list of floats
        matrix = gsl.gsl_matrix_alloc(len(data), len(data[0]))
        for i in range(len(data)):
            for j in range(len(data[i])):
                gsl.gsl_matrix_set(matrix, i, j, data[i][j])
        return matrix

    @staticmethod
    def retrieve_gsl_matrix(matrix):
        # Retrieve the elements of a GSL matrix as a 2D list of floats
        data = []
        for i in range(len(data)):
            row = []
            for j in range(len(data[i])):
                row.append(gsl.gsl_matrix_get(matrix, i, j))
            data.append(row)
        return data

    @staticmethod
    def free_gsl_matrix(matrix):
        # Free the memory allocated by a GSL matrix
        gsl.gsl_matrix_free(matrix)

