class GSLMatrix(ctypes.Structure):
    _fields_ = [("matrix", ctypes.POINTER(ctypes.c_double))
]

class GSLVector(ctypes.Structure):
    _fields_ = [("vector", ctypes.POINTER(ctypes.c_double))
]

def matrix_to_gsl(matrix: list) -> GSLMatrix:
    gsl_matrix = GSLMatrix()
    gsl_matrix.matrix = (ctypes.c_double * len(matrix[0]))(*sum(matrix, []))
    return gsl_matrix

def vector_to_gsl(vector: list) -> GSLVector:
    gsl_vector = GSLVector()
    gsl_vector.vector = (ctypes.c_double * len(vector))(*vector)
    return gsl_vector

def gsl_matrix_to_list(gsl_matrix: GSLMatrix) -> list:
    return [[gsl_matrix.matrix[i][j] for j in range(len(gsl_matrix.matrix))] for i in range(len(gsl_matrix.matrix))]

def gsl_vector_to_list(gsl_vector: GSLVector) -> list:
    return [gsl_vector.vector[i] for i in range(len(gsl_vector.vector))]

def ql_decomposition_and_unpack(A: list, tau: list):
    gsl_matrix = matrix_to_gsl(A)
    gsl_vector = vector_to_gsl(tau)
    ql_decomp = gsl.cdll.LoadLibrary("/usr/local/gsl/lib/libgslcblas.so").gsl_linalg_QL_decomp(gsl_matrix, gsl_vector)
