class GSLBlock:
    def __init__(self):
        self._block = None

    def allocate(self, n):
        if self._block is not None:
            raise RuntimeError("GSL block already allocated")
        self._block = gsl.gsl_block_alloc(ctypes.c_size_t(n))
        return bool(self._block)

    def initialize(self):
        if self._block is None:
            raise RuntimeError("GSL block not allocated")
        gsl.gsl_block_calloc(self._block)

    def free(self):
        if self._block is None:
            raise RuntimeError("GSL block not allocated")
        gslcblas.gsl_block_free(self._block)

