class GslRstatQuantileWorkspace:
    def __init__(self):
        self.workspace = None

    def allocate(self, p):
        if self.workspace is not None:
            self.free()
        self.workspace = ctypes.POINTER(ctypes.c_double)()
        result = gsl.gsl_rstat_quantile_alloc(p, self.workspace)
        return result == 0

    def reset(self):
        if self.workspace is None:
            raise ValueError("Quantile workspace not allocated")
        result = gsl.gsl_rstat_quantile_reset(self.workspace)
        return result == 0

    def add(self, value):
        if self.workspace is None:
            raise ValueError("Quantile workspace not allocated")
        result = gsl.gsl_rstat_quantile_add(value, self.workspace)
        return result == 0

    def get(self):
        if self.workspace is None:
            raise ValueError("Quantile workspace not allocated")
        quantile = ctypes.c_double()
        result = gsl.gsl_rstat_quantile_get(self.workspace, ctypes.byref(quantile))
        return quantile.value if result == 0 else None

    def free(self):
        if self.workspace is not None:
            gsl.gsl_rstat_quantile_free(self.workspace)
            self.workspace = None

