import ctypes

def cross_language_programming(N, alpha, X, Y):
    if len(X) != len(Y) or N > len(X):
        return "Error: Input arrays have different lengths or N is greater than the length of the input arrays"

    # Load GSL dynamic libraries in correct order
    try:
        gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except OSError as e:
        return "Error loading GSL dynamic libraries: " + str(e)

    # Define function prototype for cblas_daxpy
    daxpy_proto = ctypes.CFUNCTYPE(None, ctypes.c_int, ctypes.c_double, ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.POINTER(ctypes.c_double))

    # Get address of cblas_daxpy function from GSL dynamic library
    try:
        daxpy = gslcblas.gsl_block_daxpy
        daxpy.argtypes = [ctypes.c_int, ctypes.c_double, ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.POINTER(ctypes.c_double)]
    except AttributeError as e:
        return "Error getting address of cblas_daxpy function from GSL dynamic library: " + str(e)

    # Call cblas_daxpy function
    try:
        daxpy(N, alpha, X, len(X), Y)
    except Exception as e:
        return "Error calling cblas_daxpy function: " + str(e)

    return Y

